'use strict';

// Run from an authenticated KoLmafia session after `refresh all`.
// Only reads game state and writes a local JSON file; never uploads a snapshot.
var k = require('kolmafia');

function entity(value) {
    return { id: k.toInt(value), name: String(value) };
}

function counts(map, convert) {
    return Object.keys(map).map(function (name) {
        var row = entity(convert(name));
        row.quantity = Number(map[name]);
        return row;
    }).sort(function (a, b) { return a.id - b.id; });
}

function preferences() {
    var result = {};
    // Explicit gameplay fields only. Never export all preferences, cookies,
    // session hashes, saved credentials, scripts, account settings or raw HTML.
    var names = [
        'kingLiberated', 'lastAdventure', 'lastEncounter', 'currentML',
        'lastCouncilVisit', 'lastEmptiedStorage', 'knownAscensions',
        'banishedMonsters', 'banishedPhyla', 'trackedMonsters',
        'olfactedMonster', 'lastCopyableMonster', 'nextAdventure',
        '_freeRests', 'timesRested', '_cinchUsed', '_sweatOutSomeBoozeUsed',
        'sweat', '_chestXRayUsed', '_shatteringPunchUsed', '_gingerbreadMobHitUsed',
        '_monkeyPawWishesUsed', '_genieWishesUsed', '_clanFortuneBuffUsed',
        '_sourceTerminalEnhanceUses', '_sourceTerminalDigitizeUses',
        '_sourceTerminalExtrudes', '_backUpUses', '_snokebombUsed',
        '_feelHatredUsed', '_feelPrideUsed', '_feelEnvyUsed',
        '_saberForceUses', '_reflexHammerUsed', '_kgbTranquilizerDartUses',
        '_latteBanishUsed', '_latteRefillsUsed', '_photocopyUsed',
        '_cameraUsed', '_iceSculptureUsed', '_enamorangs',
        '_garboCompleted', '_neverendingPartyFreeTurns', '_snojoFreeFights',
        '_speakeasyFreeFights', '_witchessFights', '_machineTunnelsAdv',
        '_eldritchTentacleFought', '_sausageFights', '_shadowRiftCombats',
        'fullnessLimit', 'inebrietyLimit', 'spleenLimit'
    ];
    Object.keys(k.getAllProperties('quest', false)).forEach(function (name) {
        if (/^quest[LMES][0-9A-Z]/.test(name) && k.propertyHasDefault(name)) names.push(name);
    });
    names.sort().forEach(function (name) {
        if (k.propertyExists(name)) result[name] = k.getProperty(name);
    });
    return result;
}

