function main() {
    if (k.myId() <= 0 || !k.myName()) throw new Error('Log in before capturing game state.');
    if (k.currentRound() > 0 || k.handlingChoice()) throw new Error('Finish the current fight or choice before capture.');
    var started = new Date().toISOString();
    var before = { turns: k.myTurncount(), adventures: k.myAdventures(), meat: k.myMeat() };
    var equipment = {};
    k.Slot.all().forEach(function (slot) { equipment[String(slot)] = entity(k.equippedItem(slot)); });
    var stats = {};
    var permed = k.getPermedSkills();
    ['Muscle', 'Mysticality', 'Moxie'].forEach(function (name) {
        var stat = k.toStat(name);
        stats[name] = { base: k.myBasestat(stat), buffed: k.myBuffedstat(stat) };
    });
    var snapshot = {
        schemaVersion: 1,
        capturedAt: started,
        source: { client: 'KoLmafia', revision: k.getRevision(), gameDay: k.todayToString() },
        coverage: {
            freshness: 'Run refresh all immediately before capture. Values reflect KoLmafia knowledge, not an atomic server transaction.',
            preferences: 'Selected gameplay counters and default quest properties only; not an exhaustive daily-resource inventory.',
            limitations: 'No exhaustive unlock, encounter-queue, combat-history, ascension-history or Museum-rank capture.'
        },
        character: {
            id: k.myId(), name: k.myName(), class: String(k.myClass()), path: String(k.myPath()),
            sign: String(k.mySign()), level: k.myLevel(), ascensions: k.myAscensions(),
            hardcore: k.inHardcore(), canInteract: k.canInteract(), daycount: k.myDaycount(),
            turns: before.turns, totalTurns: k.totalTurnsPlayed(), adventures: before.adventures,
            hp: k.myHp(), maxHp: k.myMaxhp(), mp: k.myMp(), maxMp: k.myMaxmp(),
            fullness: k.myFullness(), fullnessLimit: k.fullnessLimit(),
            inebriety: k.myInebriety(), inebrietyLimit: k.inebrietyLimit(),
            spleen: k.mySpleenUse(), spleenLimit: k.spleenLimit(),
            meat: before.meat, closetMeat: k.myClosetMeat(), storageMeat: k.myStorageMeat(), stats: stats
        },
        items: {
            inventory: counts(k.getInventory(), k.toItem), closet: counts(k.getCloset(), k.toItem),
            storage: counts(k.getStorage(), k.toItem), freePulls: counts(k.getFreePulls(), k.toItem),
            display: k.haveDisplay() ? counts(k.getDisplay(), k.toItem) : [],
            shop: k.haveShop() ? counts(k.getShop(), k.toItem) : []
        },
        equipment: equipment,
        effects: counts(k.myEffects(), k.toEffect),
        skills: k.Skill.all().filter(function (skill) { return k.haveSkill(skill); }).map(entity),
        permedSkills: Object.keys(permed).map(function (name) {
            return { id: k.toInt(k.toSkill(name)), name: name, hardcore: permed[name] };
        }),
        familiar: entity(k.myFamiliar()),
        familiars: k.Familiar.all().filter(function (familiar) { return k.haveFamiliar(familiar); }).map(function (familiar) {
            return { id: k.toInt(familiar), species: String(familiar), name: familiar.name,
                experience: familiar.experience, weight: k.familiarWeight(familiar),
                equipment: entity(k.familiarEquippedEquipment(familiar)) };
        }),
        campground: counts(k.getCampground(), k.toItem),
        workshed: entity(k.getWorkshed()),
        preferences: preferences()
    };
    expandedState(snapshot);
    var after = { turns: k.myTurncount(), adventures: k.myAdventures(), meat: k.myMeat() };
    if (JSON.stringify(before) !== JSON.stringify(after)) throw new Error('State changed during capture; no snapshot written.');
    snapshot.captureFinishedAt = new Date().toISOString();
    var filename = 'smm-comprehensive-state-' + k.myId() + '-' + k.todayToString() + '.json';
    if (!k.bufferToFile(JSON.stringify(snapshot, null, 2) + '\n', filename)) throw new Error('Could not write snapshot.');
    k.print('SNAPSHOT_SAVED ' + filename);
}

exports.main = main;
